ruleBookInfo.init:
@js:
(function(){
  try{ if(book){ book.type=32; book.originType=32; } }catch(e){}
  var d = JSON.parse(result);
  var b = d || {};
  JSON.stringify({
    name: b.title || '',
    author: b.author || '',
    coverUrl: b.cover || '',
    intro: b.description || '',
    kind: (b.categories && b.categories[0]) || '',
    tocUrl: b.tocUrl || ''
  });
})()

ruleToc.chapterList:
@js:
(function(){
  var d = JSON.parse(result);
  var arr = d.chapters || [];
  var out = [];
  var seen = {};
  for (var i=0;i<arr.length;i++){
    var it = arr[i] || {};
    var id = String(it.id || '');
    if (!id || seen[id]) continue;
    seen[id] = 1;
    out.push({ name: it.title || '', url: id });
  }
  return out;
})()

ruleContent.content:
@js:
(function(){
  try{ if(book){ book.type=32; book.originType=32; } }catch(e){}
  var d = JSON.parse(result);
  var u = (d && d.url) || '';
  u;
})()
